import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s4-u05")
C = "A2-B1"

L(1, "Ler um anúncio de emprego", "vacature, functie, eisen, wij bieden",
  ["Compreender as partes de um anúncio de emprego"],
  vocab=[V("v-vacature","vacature","vaga (de emprego)","noun","de","vacatures"), V("v-functie","functie","função|cargo","noun","de"),
         V("v-eisen","eisen","requisitos","noun","de",note="singular: de eis"), V("v-wij-bieden","wij bieden","oferecemos","expression"),
         V("v-ervaring-met","ervaring met","experiência com/em","expression")],
  ex=[("Wij hebben een vacature voor een kok.","Temos uma vaga para cozinheiro."),("Wat zijn de eisen?","Quais são os requisitos?"),("Je hebt ervaring met Excel.","Tens experiência com Excel."),("Wij bieden een goed salaris.","Oferecemos um bom salário.")],
  review=["v-salaris","v-fulltime","v-parttime","v-ervaring"],
  cefr=C, exs=[
    MA([("vacature","vaga"),("functie","função"),("eisen","requisitos"),("wij bieden","oferecemos")], "Anúncios.", ["v-vacature","v-functie","v-eisen","v-wij-bieden"]),
    AR("vacature","a vaga","de", "De vacature.", ["v-vacature"]),
    TR("pt-nl","Quais são os requisitos?", ["Wat zijn de eisen"], "de eisen.", ["v-eisen"]),
    TR("nl-pt","Wij bieden een goed salaris.", ["Oferecemos um bom salário","Nós oferecemos um bom salário"], "wij bieden.", ["v-wij-bieden"]),
    FB("Je hebt minimaal twee jaar ervaring ___ klantenservice.", ["met","in"], "ervaring met/in.", ["v-ervaring-met"], choices=["met","van","op"], tr="Tens no mínimo dois anos de experiência em apoio ao cliente."),
    CO("text","Vacature: medewerker klantenservice (24–32 uur)", "Wij zoeken een vriendelijke medewerker klantenservice.\nWat ga je doen? Je beantwoordt vragen van klanten per telefoon en e-mail.\nWat vragen wij? Je spreekt goed Nederlands en Engels. Je hebt ervaring met klantcontact.\nWat bieden wij? Een tijdelijk contract voor een jaar, met kans op een vast contract. Een goed salaris en een reiskostenvergoeding.",
       [("Quantas horas por semana?", ["*Entre 24 e 32","40","Menos de 20"]),("Que contrato oferecem?", ["*A termo, por um ano, com hipótese de passar a sem termo","Sem termo desde o início","Só trabalho temporário de verão"]),("Que línguas pedem?", ["*Neerlandês e inglês","Só neerlandês","Neerlandês e alemão"])],
       "reiskostenvergoeding = subsídio de deslocação.", ["v-vacature","v-eisen","v-wij-bieden"]),
    MC("Na secção «Wat vragen wij?» encontra…", ["*os requisitos","o salário|Isso está em «Wat bieden wij?».","a morada|Não."], "vragen = pedir.", ["v-eisen"]),
    LI("Is deze vacature nog open?", ["Is deze vacature nog open"], "Esta vaga ainda está aberta?", "vacature.", ["v-vacature"]),
    FE(["Wij","biedt","een","goed","salaris."], 1, "bieden", "Wij → bieden.", ["v-wij-bieden"]),
    WO("Tens experiência com Excel?", ["Heb","je","ervaring","met","Excel?"], "Pergunta: verbo primeiro.", ["v-ervaring-met"]),
  ], diff=3, mins=7)

L(2, "O currículo (cv)", "Persoonlijke gegevens, opleiding, werkervaring, vaardigheden",
  ["Conhecer as secções de um cv neerlandês"],
  vocab=[V("v-cv","cv","currículo","noun","het"), V("v-opleiding","opleiding","formação (curso)","noun","de"),
         V("v-werkervaring","werkervaring","experiência profissional","noun","de"), V("v-vaardigheden","vaardigheden","competências","noun","de",note="singular: de vaardigheid"),
         V("v-diploma","diploma","diploma","noun","het")],
  ex=[("Ik stuur mijn cv mee.","Envio em anexo o meu currículo."),("Welke opleiding heb je gedaan?","Que curso fizeste?"),("Ik heb vijf jaar werkervaring.","Tenho cinco anos de experiência profissional."),("Mijn diploma is erkend in Nederland.","O meu diploma é reconhecido nos Países Baixos.")],
  gram=[G("g-cv-nl","O cv neerlandês","Costuma ter 1–2 páginas: **persoonlijke gegevens** (dados pessoais), **opleiding**, **werkervaring** (do mais recente para o mais antigo), **vaardigheden** e **talen** (línguas). Foto e data de nascimento são opcionais. Diplomas estrangeiros podem ser avaliados pelo **IDW/Nuffic**.",
    [("Talen: Portugees (moedertaal), Engels (vloeiend), Nederlands (B1)","Línguas: português (língua materna), inglês (fluente), neerlandês (B1)")])],
  review=["v-naam","v-adres","v-geboortedatum","v-studeren"],
  cefr=C, exs=[
    MA([("cv","currículo"),("opleiding","formação"),("werkervaring","experiência profissional"),("vaardigheden","competências"),("diploma","diploma")], "Secções do cv.", ["v-cv","v-opleiding","v-werkervaring","v-vaardigheden","v-diploma"]),
    AR("cv","o currículo","het", "Het cv.", ["v-cv"]),
    AR("opleiding","a formação","de", "-ing → de.", ["v-opleiding"]),
    TR("pt-nl","Tenho cinco anos de experiência profissional.", ["Ik heb vijf jaar werkervaring"], "jaar (singular) depois de número.", ["v-werkervaring"]),
    TR("nl-pt","Welke opleiding heb je gedaan?", ["Que curso fizeste","Que formação fizeste","Que curso tiraste"], "opleiding.", ["v-opleiding"]),
    MC("Onde põe «Excel, trabalho em equipa, comunicação»?", ["*Vaardigheden","Opleiding|Aí vão os cursos.","Persoonlijke gegevens|Aí vão nome, morada…"], "Competências.", ["v-vaardigheden"]),
    MC("Como descrever o seu nível de inglês «fluente»?", ["*vloeiend","vloeibaar|Isso é «líquido».","vliegend|Isso é «a voar»."], "vloeiend.", []),
    FB("Ik stuur mijn ___ mee als bijlage.", ["cv"], "het cv.", ["v-cv"], choices=["cv","vacature","functie"], tr="Envio o meu currículo em anexo."),
    LI("Mijn diploma is erkend in Nederland.", ["Mijn diploma is erkend in Nederland"], "O meu diploma é reconhecido nos Países Baixos.", "erkend = reconhecido.", ["v-diploma"]),
    WO("Que línguas falas?", ["Welke","talen","spreek","je?"], "Welke + plural.", []),
  ], diff=3, mins=6)

L(3, "A carta de motivação", "Graag solliciteer ik naar de functie van…",
  ["Escrever as frases-chave de uma carta de motivação"],
  vocab=[V("v-solliciteren","solliciteren (naar)","candidatar-se (a)","verb"), V("v-sollicitatiebrief","sollicitatiebrief","carta de motivação","noun","de"),
         V("v-gemotiveerd","gemotiveerd","motivado","adjective"), V("v-bijlage","bijlage","anexo","noun","de"),
         V("v-uitnodiging","uitnodiging","convite","noun","de")],
  ex=[("Graag solliciteer ik naar de functie van kok.","Venho candidatar-me à função de cozinheiro."),("Ik ben zeer gemotiveerd.","Estou muito motivado."),("In de bijlage vindt u mijn cv.","Em anexo encontra o meu currículo."),("Ik zie uw reactie graag tegemoet.","Aguardo a sua resposta.")],
  gram=[G("g-sollicitatiebrief","Frases-chave","Abertura: **Graag solliciteer ik naar de functie van …** (vi a vaga em …). Motivação: **Ik ben geïnteresseerd in deze functie omdat …** Fecho: **Ik zie uw reactie graag tegemoet** / **Graag licht ik mijn motivatie toe in een gesprek.** + *Met vriendelijke groet*.",
    [("Via uw website zag ik de vacature voor…","No vosso site vi a vaga para…")],
    "A carta neerlandesa é mais curta e direta do que a portuguesa: meia página a uma página.")],
  review=["v-geachte","v-met-vriendelijke-groet","v-vacature","v-cv"],
  cefr=C, exs=[
    MA([("solliciteren","candidatar-se"),("sollicitatiebrief","carta de motivação"),("gemotiveerd","motivado"),("bijlage","anexo"),("uitnodiging","convite")], "Candidaturas.", ["v-solliciteren","v-sollicitatiebrief","v-gemotiveerd","v-bijlage","v-uitnodiging"]),
    FB("Graag solliciteer ik ___ de functie van receptionist.", ["naar"], "solliciteren naar.", ["v-solliciteren"], choices=["naar","voor","op"], tr="Venho candidatar-me à função de rececionista."),
    TR("pt-nl","Em anexo encontra o meu currículo.", ["In de bijlage vindt u mijn cv","Als bijlage vindt u mijn cv","Bijgevoegd vindt u mijn cv"], "In de bijlage vindt u…", ["v-bijlage"]),
    TR("nl-pt","Ik zie uw reactie graag tegemoet.", ["Aguardo a sua resposta","Fico a aguardar a sua resposta","Aguardo com interesse a sua resposta"], "Fórmula de fecho.", []),
    AR("bijlage","o anexo","de", "De bijlage.", ["v-bijlage"]),
    MC("Qual é a melhor abertura?", ["*Graag solliciteer ik naar de functie van verkoper.","Hoi! Ik wil die baan.|Demasiado informal.","Ik ben Pedro en ik ben 30.|Não diz a que se candidata."], "Abertura padrão.", ["v-solliciteren"]),
    FE(["Ik","ben","geïnteresseerd","in","deze","functie","omdat","ik","heb","ervaring."], 8, "ervaring heb", "Depois de omdat, o verbo vai para o fim: omdat ik ervaring heb.", []),
    WO("Estou muito motivado para esta função.", ["Ik","ben","zeer","gemotiveerd","voor","deze","functie"], "gemotiveerd voor.", ["v-gemotiveerd"]),
    LI("Ik heb een uitnodiging voor een gesprek gekregen!", ["Ik heb een uitnodiging voor een gesprek gekregen"], "Recebi um convite para uma entrevista!", "uitnodiging.", ["v-uitnodiging"]),
    SW("Escreva a abertura e o fecho de uma carta de motivação para uma vaga de rececionista num hotel.", ["Geachte heer/mevrouw,\nGraag solliciteer ik naar de functie van receptionist. … Ik zie uw reactie graag tegemoet.\nMet vriendelijke groet,"], ["**Geachte heer/mevrouw**", "**Graag solliciteer ik naar de functie van …**", "Fecho educado + **Met vriendelijke groet**"], 15, "Estrutura da carta.", ["v-solliciteren","v-sollicitatiebrief"]),
  ], diff=4, mins=8)

L(4, "Falar das suas qualidades", "Ik ben flexibel, nauwkeurig en werk graag in een team.",
  ["Descrever qualidades pessoais e profissionais"],
  vocab=[V("v-flexibel","flexibel","flexível","adjective"), V("v-nauwkeurig","nauwkeurig","rigoroso|meticuloso","adjective"),
         V("v-zelfstandig","zelfstandig","autónomo|independente","adjective"), V("v-betrouwbaar","betrouwbaar","de confiança|fiável","adjective"),
         V("v-teamspeler","teamspeler","pessoa que trabalha bem em equipa","noun","de")],
  ex=[("Ik ben flexibel en betrouwbaar.","Sou flexível e de confiança."),("Ik kan goed zelfstandig werken.","Trabalho bem de forma autónoma."),("Ik ben een echte teamspeler.","Trabalho muito bem em equipa."),("Ik werk nauwkeurig.","Trabalho com rigor.")],
  gram=[G("g-adj-als-adv","Adjetivo como advérbio","Em neerlandês o adjetivo serve também de advérbio, **sem mudar**: *Ik ben nauwkeurig* (sou rigoroso) / *Ik werk nauwkeurig* (trabalho com rigor).",
    [("Hij praat snel.","Ele fala depressa."),("Zij werkt zelfstandig.","Ela trabalha de forma autónoma.")],
    "Em português muitas vezes juntamos «-mente» ou «com…»; em neerlandês não é preciso.")],
  review=["v-goed","v-samenwerken","v-gemotiveerd"],
  cefr=C, exs=[
    MA([("flexibel","flexível"),("nauwkeurig","rigoroso"),("zelfstandig","autónomo"),("betrouwbaar","de confiança")], "Qualidades.", ["v-flexibel","v-nauwkeurig","v-zelfstandig","v-betrouwbaar"]),
    TR("pt-nl","Sou flexível e de confiança.", ["Ik ben flexibel en betrouwbaar"], "Adjetivos predicativos.", ["v-flexibel","v-betrouwbaar"]),
    TR("pt-nl","Trabalho com rigor.", ["Ik werk nauwkeurig"], "Adjetivo = advérbio.", ["v-nauwkeurig"]),
    TR("nl-pt","Ik kan goed zelfstandig werken.", ["Trabalho bem de forma autónoma","Consigo trabalhar bem de forma autónoma","Sei trabalhar bem sozinho"], "zelfstandig.", ["v-zelfstandig"]),
    FE(["Ik","werk","nauwkeurige."], 2, "nauwkeurig", "Como advérbio, o adjetivo não leva -e.", ["v-nauwkeurig"]),
    MC("«Een echte teamspeler» é alguém que…", ["*trabalha bem com os outros","joga futebol|Aqui é sentido figurado.","trabalha sempre sozinho|É o contrário."], "team + speler.", ["v-teamspeler"]),
    FB("Ik ben een ___ werknemer: ik kom altijd op tijd.", ["betrouwbare"], "Antes de nome de-woord → -e.", ["v-betrouwbaar"], choices=["betrouwbare","betrouwbaar","betrouwbaren"], tr="Sou um trabalhador de confiança: chego sempre a horas."),
    LI("Wat zijn uw sterke punten?", ["Wat zijn uw sterke punten"], "Quais são os seus pontos fortes?", "sterke punten.", []),
    DL([("Interviewer","Hoe zou u uzelf omschrijven?","Como se descreveria?"),("Candidata","")], ["*Ik ben nauwkeurig en flexibel, en ik werk graag in een team.","Ik ben 35 jaar.|Não descreve qualidades.","Ik omschrijf.|Não responde."], "Qualidades.", ["v-nauwkeurig","v-flexibel"]),
    SW("Descreva-se em 2 frases com três qualidades desta lição.", ["Ik ben flexibel en betrouwbaar. Ik kan goed zelfstandig werken, maar ik ben ook een teamspeler."], ["Três qualidades", "Pelo menos um adjetivo usado como advérbio (werk …)", "Sem -e depois de ben/werk"], 10, "Autodescrição.", ["v-flexibel","v-betrouwbaar","v-zelfstandig"]),
  ], diff=3, mins=7)

L(5, "Enviar a candidatura", "Formulário online, prazo, confirmação de receção",
  ["Seguir o processo de candidatura e compreender as respostas"],
  vocab=[V("v-reageren","reageren (op)","responder (a)|candidatar-se","verb",note="Reageer vóór 1 mei."), V("v-uiterlijk","uiterlijk","o mais tardar","adverb"),
         V("v-ontvangstbevestiging","ontvangstbevestiging","confirmação de receção","noun","de"), V("v-afwijzing","afwijzing","recusa|resposta negativa","noun","de"),
         V("v-sollicitatiegesprek","sollicitatiegesprek","entrevista de emprego","noun","het")],
  ex=[("Reageer uiterlijk 15 mei.","Candidate-se até 15 de maio, o mais tardar."),("We hebben uw sollicitatie ontvangen.","Recebemos a sua candidatura."),("Helaas hebben we gekozen voor een andere kandidaat.","Infelizmente escolhemos outro candidato."),("We nodigen u uit voor een sollicitatiegesprek.","Convidamo-lo para uma entrevista.")],
  review=["v-solliciteren","v-bijlage","v-helaas","v-uitnodiging"],
  cefr=C, exs=[
    MA([("reageren","candidatar-se/responder"),("uiterlijk","o mais tardar"),("ontvangstbevestiging","confirmação de receção"),("afwijzing","recusa"),("sollicitatiegesprek","entrevista")], "Processo.", ["v-reageren","v-uiterlijk","v-ontvangstbevestiging","v-afwijzing","v-sollicitatiegesprek"]),
    TR("nl-pt","Reageer uiterlijk 15 mei.", ["Candidate-se até 15 de maio","Responda até 15 de maio","Candidate-se o mais tardar a 15 de maio"], "uiterlijk = o mais tardar.", ["v-uiterlijk"]),
    MC("«Helaas hebben we gekozen voor een andere kandidaat» é…", ["*uma recusa","um convite|Não, escolheram outra pessoa.","uma confirmação de receção|Já foi decidido."], "afwijzing.", ["v-afwijzing"]),
    MC("Recebe: «We nodigen u uit voor een gesprek op dinsdag om 10.00 uur.»", ["*É um convite para entrevista na terça às 10h.","É uma recusa.|Não.","É um pedido de documentos.|Não."], "uitnodigen.", ["v-sollicitatiegesprek"]),
    AR("sollicitatiegesprek","a entrevista de emprego","het", "Composto: o último elemento decide → het gesprek.", ["v-sollicitatiegesprek"]),
    FB("U kunt ___ via ons online formulier.", ["reageren"], "reageren = candidatar-se.", ["v-reageren"], choices=["reageren","afwijzen","ontvangen"], tr="Pode candidatar-se através do nosso formulário online."),
    CO("text","E-mail van HR", "Beste Pedro,\n\nBedankt voor je sollicitatie voor de functie van medewerker klantenservice. We hebben je brief en cv in goede orde ontvangen. Je hoort uiterlijk vrijdag 12 april of we je uitnodigen voor een gesprek.\n\nMet vriendelijke groet,\nAfdeling HR",
       [("Que tipo de e-mail é?", ["*Confirmação de receção","Recusa","Proposta de contrato"]),("Quando terá resposta?", ["*Até sexta-feira, 12 de abril","Hoje","Daqui a um mês"])],
       "in goede orde ontvangen = recebido corretamente.", ["v-ontvangstbevestiging","v-uiterlijk"]),
    LI("We nodigen u graag uit voor een sollicitatiegesprek.", ["We nodigen u graag uit voor een sollicitatiegesprek","Wij nodigen u graag uit voor een sollicitatiegesprek"], "Temos o prazer de o convidar para uma entrevista.", "uitnodigen (separável).", ["v-sollicitatiegesprek"]),
    WO("Recebemos a sua candidatura.", ["We","hebben","uw","sollicitatie","ontvangen"], "Perfectum.", []),
    TR("pt-nl","Obrigado pelo convite.", ["Bedankt voor de uitnodiging","Dank u wel voor de uitnodiging","Dank je wel voor de uitnodiging","Hartelijk dank voor de uitnodiging"], "bedankt voor.", ["v-uitnodiging"]),
  ], diff=3, mins=7)

W()
